    {
      "answer": "A",
      "reason_rejected": "Novation discharges duties by agreement, requiring consent of the parties, not by operation of law."
    },
    {
      "answer": "B",
      "reason_rejected": "Accord and satisfaction is a voluntary settlement, also a discharge by agreement."
    },
    {
      "answer": "C",
      "reason_rejected": "Anticipatory repudiation is a breach that gives a right to terminate, but the discharge is elective, not automatic."
    }
  ]
